import{_ as t,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const l=JSON.parse('{"title":"Mục 6.5 – Bản Quyền Phần Mềm & Sở Hữu Trí Tuệ","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.5-ban-quyen-phan-mem.md","filePath":"chuong-6/6.5-ban-quyen-phan-mem.md","lastUpdated":1775336269000}'),o={name:"chuong-6/6.5-ban-quyen-phan-mem.md"};function r(g,n,c,p,e,m){return i(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="muc-6-5-–-ban-quyen-phan-mem-so-huu-tri-tue" tabindex="-1">Mục 6.5 – Bản Quyền Phần Mềm &amp; Sở Hữu Trí Tuệ <a class="header-anchor" href="#muc-6-5-–-ban-quyen-phan-mem-so-huu-tri-tue" aria-label="Permalink to &quot;Mục 6.5 – Bản Quyền Phần Mềm &amp; Sở Hữu Trí Tuệ&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Tại sao phần mềm cần bản quyền?</strong></p><p>Hãy tưởng tượng bạn mất 3 năm viết một cuốn tiểu thuyết. Ngay khi xuất bản, người khác photo cóp y nguyên và bán giá rẻ hơn. Bạn có tức không? Tất nhiên là có – bởi vì đó là <strong>thành quả lao động trí tuệ</strong> của bạn.</p><p>Phần mềm cũng vậy. Một ứng dụng như Microsoft Office hay Adobe Photoshop tốn <strong>hàng trăm triệu USD</strong> và <strong>hàng nghìn lập trình viên</strong> trong nhiều năm mới tạo ra. Khi ai đó dùng crack (bẻ khóa), họ đang <strong>ăn cắp thành quả lao động</strong> của người khác.</p><p>Bản quyền phần mềm không chỉ bảo vệ công ty lớn – nó bảo vệ cả những lập trình viên độc lập, sinh viên mới ra trường tạo ra ứng dụng đầu tiên của mình.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="ban-quyen-phan-mem-la-gi" tabindex="-1">Bản quyền phần mềm là gì? <a class="header-anchor" href="#ban-quyen-phan-mem-la-gi" aria-label="Permalink to &quot;Bản quyền phần mềm là gì?&quot;">​</a></h3><p><strong>Bản quyền phần mềm (Software Copyright)</strong> là quyền pháp lý bảo vệ tác giả/nhà phát triển phần mềm, ngăn người khác sao chép, phân phối, chỉnh sửa hoặc bán phần mềm mà không được phép.</p><p>Tại Việt Nam, bản quyền phần mềm được bảo vệ theo:</p><ul><li><strong>Luật Sở hữu trí tuệ 2005</strong> (sửa đổi 2009, 2019, 2022)</li><li><strong>Bộ luật Hình sự 2015</strong> (Điều 225 – Tội xâm phạm quyền tác giả)</li></ul><h3 id="cac-loai-giay-phep-phan-mem-software-license" tabindex="-1">Các loại giấy phép phần mềm (Software License) <a class="header-anchor" href="#cac-loai-giay-phep-phan-mem-software-license" aria-label="Permalink to &quot;Các loại giấy phép phần mềm (Software License)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại giấy phép</th><th>Mô tả</th><th>Ví dụ</th></tr></thead><tbody><tr><td><strong>Proprietary (Độc quyền)</strong></td><td>Mua/thuê mới dùng được, không được xem code</td><td>Microsoft Windows, Adobe Photoshop</td></tr><tr><td><strong>Freeware (Miễn phí)</strong></td><td>Dùng miễn phí nhưng không được sửa code</td><td>WinRAR, VLC Media Player</td></tr><tr><td><strong>Shareware (Dùng thử)</strong></td><td>Dùng thử miễn phí, sau đó phải trả tiền</td><td>Nhiều phần mềm diệt virus</td></tr><tr><td><strong>Open Source (Mã nguồn mở)</strong></td><td>Xem, sửa, chia sẻ code tự do (có điều kiện)</td><td>Linux, Firefox, LibreOffice</td></tr><tr><td><strong>Public Domain (Công cộng)</strong></td><td>Không có bản quyền, ai cũng dùng được</td><td>Một số phần mềm cũ hết hạn bảo hộ</td></tr></tbody></table><h3 id="phan-mem-lau-pirated-software-la-gi" tabindex="-1">Phần mềm lậu (Pirated Software) là gì? <a class="header-anchor" href="#phan-mem-lau-pirated-software-la-gi" aria-label="Permalink to &quot;Phần mềm lậu (Pirated Software) là gì?&quot;">​</a></h3><p><strong>Phần mềm lậu (Software Piracy)</strong> là việc sử dụng, sao chép hoặc phân phối phần mềm vi phạm điều khoản bản quyền, bao gồm:</p><ul><li><strong>Cracking:</strong> Bẻ khóa phần mềm để dùng không cần mua</li><li><strong>Keygen:</strong> Tạo mã kích hoạt giả</li><li><strong>Warez:</strong> Chia sẻ phần mềm bản quyền trên mạng</li><li><strong>Cài cho nhiều máy:</strong> Mua 1 bản nhưng cài cho nhiều máy tính (vi phạm điều khoản license)</li><li><strong>Counterfeit (Hàng nhái):</strong> Bán đĩa/USB chứa phần mềm giả mạo</li></ul><h3 id="phan-mem-ma-nguon-mo-open-source" tabindex="-1">Phần mềm mã nguồn mở (Open Source) <a class="header-anchor" href="#phan-mem-ma-nguon-mo-open-source" aria-label="Permalink to &quot;Phần mềm mã nguồn mở (Open Source)&quot;">​</a></h3><p><strong>Phần mềm mã nguồn mở</strong> không có nghĩa là &quot;hoàn toàn tự do không giới hạn&quot;. Vẫn có điều kiện:</p><p><strong>Giấy phép GPL (General Public License):</strong></p><ul><li>Được dùng, sửa, phân phối miễn phí</li><li><strong>Nhưng:</strong> Nếu bạn phân phối phần mềm dựa trên GPL, phần mềm của bạn <strong>cũng phải là GPL</strong> (copyleft)</li><li>Ví dụ: Linux kernel</li></ul><p><strong>Giấy phép MIT:</strong></p><ul><li>Rất thoải mái: dùng, sửa, bán đều được</li><li>Chỉ cần giữ thông báo bản quyền gốc</li><li>Ví dụ: React.js, jQuery</li></ul><p><strong>Giấy phép Apache 2.0:</strong></p><ul><li>Tương tự MIT nhưng có thêm điều khoản về bằng sáng chế</li><li>Ví dụ: Android, Kubernetes</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>Tại sao không nên dùng phần mềm lậu?</strong></p><p><strong>Lý do pháp lý:</strong></p><ul><li>Vi phạm Luật Sở hữu trí tuệ → có thể bị phạt tiền hoặc tù</li><li>Doanh nghiệp dùng phần mềm lậu có thể bị kiện, mất uy tín</li></ul><p><strong>Lý do an toàn:</strong></p><ul><li>Phần mềm crack thường bị <strong>cài sẵn malware</strong> (virus, trojan, spyware, ransomware)</li><li>Không được cập nhật bảo mật → dễ bị khai thác lỗ hổng</li><li>&quot;Miễn phí&quot; nhưng trả bằng <strong>dữ liệu cá nhân và bảo mật máy tính</strong></li></ul><p><strong>Lý do đạo đức:</strong></p><ul><li>Lập trình viên bỏ thời gian, công sức, tiền bạc tạo ra phần mềm</li><li>Dùng lậu = không tôn trọng công sức người khác</li><li>Nếu ai cũng dùng lậu, không ai kinh doanh phần mềm được → ít sản phẩm chất lượng hơn</li></ul><p><strong>So sánh thực tế:</strong></p><table tabindex="0"><thead><tr><th>Hành vi</th><th>Tương đương offline</th></tr></thead><tbody><tr><td>Dùng phần mềm crack</td><td>Vào rạp phim không mua vé</td></tr><tr><td>Chia sẻ link download phần mềm lậu</td><td>Bán đĩa lậu ở chợ</td></tr><tr><td>Cài 1 license cho 10 máy</td><td>Mua 1 cuốn sách rồi photo cho cả lớp</td></tr></tbody></table><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="cach-chon-phan-mem-hop-phap-va-mien-phi" tabindex="-1">Cách chọn phần mềm hợp pháp và miễn phí: <a class="header-anchor" href="#cach-chon-phan-mem-hop-phap-va-mien-phi" aria-label="Permalink to &quot;Cách chọn phần mềm hợp pháp và miễn phí:&quot;">​</a></h3><ol><li><strong>Xác định nhu cầu</strong> → Bạn cần phần mềm làm gì?</li><li><strong>Tìm kiếm thay thế mã nguồn mở</strong> → Thường có lựa chọn miễn phí hợp pháp</li><li><strong>Tải từ nguồn chính thức</strong> → Website chính thức của nhà phát triển</li><li><strong>Kiểm tra giấy phép</strong> → Đọc điều khoản sử dụng</li><li><strong>Cài đặt và cập nhật</strong> → Luôn dùng phiên bản mới nhất</li></ol><h3 id="cac-phan-mem-mien-phi-thay-the-hop-phap" tabindex="-1">Các phần mềm miễn phí thay thế hợp pháp: <a class="header-anchor" href="#cac-phan-mem-mien-phi-thay-the-hop-phap" aria-label="Permalink to &quot;Các phần mềm miễn phí thay thế hợp pháp:&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Phần mềm có phí</th><th>Thay thế miễn phí hợp pháp</th></tr></thead><tbody><tr><td>Microsoft Office</td><td>LibreOffice, Google Docs</td></tr><tr><td>Adobe Photoshop</td><td>GIMP, Canva (free tier)</td></tr><tr><td>Windows</td><td>Ubuntu, Linux Mint</td></tr><tr><td>AutoCAD</td><td>FreeCAD, LibreCAD</td></tr><tr><td>Adobe Premiere</td><td>DaVinci Resolve (free)</td></tr><tr><td>WinRAR (trial)</td><td>7-Zip (hoàn toàn miễn phí)</td></tr></tbody></table><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-phan-biet-cac-loai-phan-mem" tabindex="-1">Ví dụ 1 – Cơ bản: Phân biệt các loại phần mềm <a class="header-anchor" href="#vi-du-1-–-co-ban-phan-biet-cac-loai-phan-mem" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Phân biệt các loại phần mềm&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn cần phần mềm soạn thảo văn bản. Bạn có các lựa chọn:</p><ul><li><strong>A.</strong> Tải crack Microsoft Word từ website lạ</li><li><strong>B.</strong> Mua Microsoft Office 365 (khoảng 120.000 đồng/tháng)</li><li><strong>C.</strong> Dùng LibreOffice Writer (miễn phí, mã nguồn mở)</li><li><strong>D.</strong> Dùng Google Docs (miễn phí, chỉ cần internet)</li></ul><p><strong>Phân tích:</strong></p><ul><li>A = <strong>Vi phạm pháp luật + nguy hiểm</strong> (malware)</li><li>B = <strong>Hợp pháp, có phí</strong> – phù hợp khi cần tính năng chuyên nghiệp</li><li>C = <strong>Hợp pháp, miễn phí</strong> – đủ dùng cho học sinh, sinh viên</li><li>D = <strong>Hợp pháp, miễn phí</strong> – tiện lợi, có thể dùng mọi thiết bị</li></ul><p><strong>Lựa chọn tốt nhất cho học sinh:</strong> C hoặc D</p><hr><h3 id="vi-du-2-–-thuc-te-doanh-nghiep-bi-phat-vi-dung-phan-mem-lau" tabindex="-1">Ví dụ 2 – Thực tế: Doanh nghiệp bị phạt vì dùng phần mềm lậu <a class="header-anchor" href="#vi-du-2-–-thuc-te-doanh-nghiep-bi-phat-vi-dung-phan-mem-lau" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Doanh nghiệp bị phạt vì dùng phần mềm lậu&quot;">​</a></h3><p><strong>Tình huống thực tế:</strong> Nhiều doanh nghiệp tại Việt Nam đã bị kiểm tra và phạt nặng vì dùng phần mềm Microsoft, Adobe không có bản quyền.</p><p><strong>Mức phạt điển hình:</strong></p><ul><li>Phạt tiền: <strong>50-100 triệu đồng</strong> (hành chính)</li><li>Phải mua bản quyền hợp lệ ngay lập tức</li><li>Tổn hại uy tín doanh nghiệp</li></ul><p><strong>Cách kiểm tra:</strong> Microsoft và các công ty phần mềm có đội ngũ kiểm tra. Họ có thể nhận báo cáo từ nhân viên, đối tác, hoặc kiểm tra từ xa qua cơ chế xác thực.</p><hr><h3 id="vi-du-3-–-nang-cao-ban-tao-ra-phan-mem-quyen-cua-ban-la-gi" tabindex="-1">Ví dụ 3 – Nâng cao: Bạn tạo ra phần mềm, quyền của bạn là gì? <a class="header-anchor" href="#vi-du-3-–-nang-cao-ban-tao-ra-phan-mem-quyen-cua-ban-la-gi" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Bạn tạo ra phần mềm, quyền của bạn là gì?&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn học lập trình và tạo một ứng dụng quản lý điểm cho trường học. Một trường khác muốn dùng ứng dụng của bạn.</p><p><strong>Bạn có thể:</strong></p><ol><li><strong>Giữ bản quyền</strong> → Phần mềm tự động có bản quyền ngay khi bạn tạo ra</li><li><strong>Cấp phép miễn phí</strong> → Cho phép trường đó dùng không mất tiền</li><li><strong>Cấp phép có phí</strong> → Thu tiền license hàng năm</li><li><strong>Phát hành mã nguồn mở</strong> → Chia sẻ code để cộng đồng cùng cải thiện</li><li><strong>Bán đứt</strong> → Bán toàn bộ quyền sở hữu cho bên khác</li></ol><p><strong>Điều quan trọng:</strong> Bạn <strong>không cần đăng ký</strong> để có bản quyền – bản quyền tự động phát sinh khi tác phẩm được tạo ra. Tuy nhiên, đăng ký với Cục Bản quyền tác giả giúp bạn có bằng chứng pháp lý mạnh hơn nếu xảy ra tranh chấp.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-cac-loai-giay-phep-phan-mem-pho-bien" tabindex="-1">So sánh các loại giấy phép phần mềm phổ biến <a class="header-anchor" href="#so-sanh-cac-loai-giay-phep-phan-mem-pho-bien" aria-label="Permalink to &quot;So sánh các loại giấy phép phần mềm phổ biến&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Giấy phép</th><th>Xem code?</th><th>Sửa code?</th><th>Phân phối?</th><th>Bán được không?</th></tr></thead><tbody><tr><td>Proprietary</td><td>❌</td><td>❌</td><td>❌</td><td>Chỉ công ty gốc</td></tr><tr><td>Freeware</td><td>❌</td><td>❌</td><td>Thường được</td><td>❌</td></tr><tr><td>GPL</td><td>✅</td><td>✅</td><td>✅ (phải giữ GPL)</td><td>❌ (phải mở code)</td></tr><tr><td>MIT</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Apache 2.0</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><h3 id="so-sanh-phan-mem-hop-phap-va-phan-mem-lau" tabindex="-1">So sánh phần mềm hợp pháp và phần mềm lậu <a class="header-anchor" href="#so-sanh-phan-mem-hop-phap-va-phan-mem-lau" aria-label="Permalink to &quot;So sánh phần mềm hợp pháp và phần mềm lậu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Phần mềm hợp pháp</th><th>Phần mềm lậu</th></tr></thead><tbody><tr><td>Chi phí</td><td>Có phí hoặc miễn phí hợp lệ</td><td>&quot;Miễn phí&quot;</td></tr><tr><td>An toàn</td><td>Được kiểm tra bảo mật</td><td>Có thể chứa malware</td></tr><tr><td>Cập nhật</td><td>Được cập nhật thường xuyên</td><td>Không có/cập nhật rủi ro</td></tr><tr><td>Hỗ trợ</td><td>Có hỗ trợ từ nhà sản xuất</td><td>Không có hỗ trợ</td></tr><tr><td>Pháp lý</td><td>Hoàn toàn hợp pháp</td><td>Vi phạm pháp luật</td></tr><tr><td>Đạo đức</td><td>Tôn trọng công sức người tạo</td><td>Không tôn trọng</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ <strong>Bản quyền phần mềm</strong> = quyền pháp lý bảo vệ người tạo phần mềm</li><li>✅ <strong>Proprietary</strong> = phần mềm độc quyền, phải trả tiền</li><li>✅ <strong>Open Source</strong> = mã nguồn mở, được xem/sửa code (có điều kiện)</li><li>✅ <strong>Freeware</strong> = miễn phí nhưng không được sửa code</li><li>✅ <strong>Phần mềm lậu</strong> = vi phạm pháp luật + nguy hiểm (malware)</li><li>✅ <strong>GPL</strong> = open source nhưng phần mềm phái sinh cũng phải là GPL</li><li>✅ <strong>MIT</strong> = open source thoải mái nhất, được dùng cho mục đích thương mại</li><li>✅ Bản quyền tự động phát sinh khi tác phẩm được tạo ra, không cần đăng ký</li><li>✅ Thay thế hợp pháp miễn phí: <strong>LibreOffice</strong> (Word), <strong>GIMP</strong> (Photoshop), <strong>7-Zip</strong> (WinRAR)</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-freeware-khac-voi-open-source-nhu-the-nao" tabindex="-1">Câu 1 (Dễ): &quot;Freeware&quot; khác với &quot;Open Source&quot; như thế nào? <a class="header-anchor" href="#cau-1-de-freeware-khac-voi-open-source-nhu-the-nao" aria-label="Permalink to &quot;Câu 1 (Dễ): &quot;Freeware&quot; khác với &quot;Open Source&quot; như thế nào?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Freeware là phần mềm miễn phí sử dụng nhưng <strong>không được xem hoặc sửa mã nguồn</strong> (code vẫn là bí mật của nhà sản xuất). Open Source là phần mềm mà <strong>mã nguồn được công khai</strong>, người dùng có thể xem, sửa và phân phối lại (tùy theo giấy phép cụ thể).</p></blockquote><hr><h3 id="cau-2-de-hanh-vi-nao-sau-đay-vi-pham-ban-quyen-phan-mem" tabindex="-1">Câu 2 (Dễ): Hành vi nào sau đây vi phạm bản quyền phần mềm? <a class="header-anchor" href="#cau-2-de-hanh-vi-nao-sau-đay-vi-pham-ban-quyen-phan-mem" aria-label="Permalink to &quot;Câu 2 (Dễ): Hành vi nào sau đây vi phạm bản quyền phần mềm?&quot;">​</a></h3><p><strong>A.</strong> Tải LibreOffice từ website chính thức<br><strong>B.</strong> Dùng crack để kích hoạt Microsoft Office<br><strong>C.</strong> Sử dụng Google Docs để soạn thảo văn bản<br><strong>D.</strong> Cài đặt Ubuntu Linux trên máy tính</p><blockquote><p><strong>Đáp án: B</strong> – Dùng crack để kích hoạt phần mềm có bản quyền là hành vi vi phạm Luật Sở hữu trí tuệ. A, C, D đều là các lựa chọn hợp pháp.</p></blockquote><hr><h3 id="cau-3-trung-binh-tai-sao-phan-mem-crack-be-khoa-lai-nguy-hiem-cho-may-tinh-cua-ban" tabindex="-1">Câu 3 (Trung bình): Tại sao phần mềm crack (bẻ khóa) lại nguy hiểm cho máy tính của bạn? <a class="header-anchor" href="#cau-3-trung-binh-tai-sao-phan-mem-crack-be-khoa-lai-nguy-hiem-cho-may-tinh-cua-ban" aria-label="Permalink to &quot;Câu 3 (Trung bình): Tại sao phần mềm crack (bẻ khóa) lại nguy hiểm cho máy tính của bạn?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Phần mềm crack nguy hiểm vì: (1) Thường được <strong>chèn thêm malware</strong> (virus, trojan, ransomware, spyware) bởi người tạo crack – đây là cách họ kiếm lợi; (2) <strong>Không nhận được bản vá bảo mật</strong> – phần mềm không được cập nhật để vá lỗ hổng; (3) Phần mềm crack phải vô hiệu hóa một số cơ chế bảo vệ của hệ điều hành, làm máy dễ bị tấn công hơn; (4) Có thể <strong>đánh cắp dữ liệu cá nhân</strong> (mật khẩu, thông tin ngân hàng).</p></blockquote><hr><h3 id="cau-4-trung-binh-giay-phep-gpl-va-giay-phep-mit-khac-nhau-o-điem-nao-quan-trong-nhat" tabindex="-1">Câu 4 (Trung bình): Giấy phép GPL và giấy phép MIT khác nhau ở điểm nào quan trọng nhất? <a class="header-anchor" href="#cau-4-trung-binh-giay-phep-gpl-va-giay-phep-mit-khac-nhau-o-điem-nao-quan-trong-nhat" aria-label="Permalink to &quot;Câu 4 (Trung bình): Giấy phép GPL và giấy phép MIT khác nhau ở điểm nào quan trọng nhất?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Điểm khác biệt quan trọng nhất là <strong>điều khoản copyleft của GPL</strong>: Nếu bạn tạo phần mềm dựa trên code có giấy phép GPL và phân phối phần mềm đó, <strong>phần mềm của bạn cũng phải được phát hành dưới GPL</strong> (mã nguồn mở). Trong khi đó, giấy phép MIT cho phép bạn <strong>sử dụng code MIT trong phần mềm đóng (proprietary)</strong> và bán nó mà không cần mở mã nguồn – chỉ cần giữ lại thông báo bản quyền gốc.</p></blockquote><hr><h3 id="cau-5-van-dung-ban-muon-tao-mot-ung-dung-hoc-tu-vung-tieng-anh-va-chia-se-mien-phi-cho-cong-đong-đong-thoi-muon-nguoi-khac-co-the-cai-thien-ung-dung-giay-phep-nao-phu-hop-nhat-tai-sao" tabindex="-1">Câu 5 (Vận dụng): Bạn muốn tạo một ứng dụng học từ vựng tiếng Anh và chia sẻ miễn phí cho cộng đồng, đồng thời muốn người khác có thể cải thiện ứng dụng. Giấy phép nào phù hợp nhất? Tại sao? <a class="header-anchor" href="#cau-5-van-dung-ban-muon-tao-mot-ung-dung-hoc-tu-vung-tieng-anh-va-chia-se-mien-phi-cho-cong-đong-đong-thoi-muon-nguoi-khac-co-the-cai-thien-ung-dung-giay-phep-nao-phu-hop-nhat-tai-sao" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Bạn muốn tạo một ứng dụng học từ vựng tiếng Anh và chia sẻ miễn phí cho cộng đồng, đồng thời muốn người khác có thể cải thiện ứng dụng. Giấy phép nào phù hợp nhất? Tại sao?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Phù hợp nhất là <strong>giấy phép MIT</strong> hoặc <strong>Apache 2.0</strong>:</p><ul><li><strong>MIT:</strong> Đơn giản, cho phép cộng đồng dùng, sửa, chia sẻ tự do nhất. Người khác có thể fork và phát triển thêm dù mục đích thương mại hay phi thương mại.</li><li><strong>Apache 2.0:</strong> Tương tự MIT nhưng có thêm điều khoản về bằng sáng chế, phù hợp hơn nếu lo ngại về tranh chấp bằng sáng chế.</li><li><strong>Không nên dùng GPL</strong> nếu muốn cho phép người khác dùng trong dự án đóng.</li><li>Dù chọn giấy phép nào, hãy <strong>đăng code lên GitHub</strong> và ghi rõ file LICENSE.</li></ul></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;Open source = miễn phí hoàn toàn, làm gì cũng được&quot;</td><td>Open source vẫn có điều kiện giấy phép; vi phạm điều kiện vẫn là vi phạm pháp luật</td></tr><tr><td>&quot;Phần mềm crack chỉ vi phạm nếu bị bắt&quot;</td><td>Vi phạm xảy ra ngay khi cài đặt, không phụ thuộc vào việc có bị phát hiện không</td></tr><tr><td>&quot;Tôi không bán lại phần mềm lậu nên không sao&quot;</td><td>Chỉ cần sử dụng phần mềm vi phạm điều khoản bản quyền là đã vi phạm pháp luật</td></tr><tr><td>&quot;Freeware thì dùng thoải mái không cần lo&quot;</td><td>Vẫn phải tuân theo điều khoản sử dụng của freeware (ví dụ: không dùng thương mại)</td></tr><tr><td>&quot;Phần mềm mã nguồn mở thì ai viết cũng chả quan tâm&quot;</td><td>Tác giả vẫn giữ bản quyền; họ chỉ cấp phép rộng hơn nhưng vẫn có quyền tác giả</td></tr><tr><td>&quot;Dùng lậu chỉ công ty lớn mới bị kiểm tra&quot;</td><td>Cá nhân cũng có thể bị xử lý, đặc biệt khi vi phạm rõ ràng</td></tr></tbody></table>',92)])])}const d=t(o,[["render",r]]);export{l as __pageData,d as default};
